import SwiftUI

struct ModelSettingsView: View {
    @Environment(AgentProfile.self) private var profile
    @State private var baseURL="";@State private var model="";@State private var key="";@State private var reveal=false;@State private var models:[String]=[];@State private var loading=false;@State private var message:String?
    var body:some View{Form{Section("服务"){TextField("https://api.openai.com",text:$baseURL).textInputAutocapitalization(.never).keyboardType(.URL).autocorrectionDisabled();HStack{Group{if reveal{TextField("API Key",text:$key)}else{SecureField(profile.hasAPIKey ? "已保存，留空不修改":"API Key",text:$key)}}.textInputAutocapitalization(.never).autocorrectionDisabled();Button{reveal.toggle()}label:{Image(systemName:reveal ? "eye.slash":"eye")}.buttonStyle(.plain)}}footer:{Text("密钥只存入系统 Keychain，不写入配置、日志或 Git。")};Section("模型"){TextField("模型 ID",text:$model).textInputAutocapitalization(.never).autocorrectionDisabled();Button{Task{await loadModels()}}label:{HStack{Text("获取模型列表");Spacer();if loading{ProgressView()}}}.disabled(loading);if !models.isEmpty{Picker("选择模型",selection:$model){ForEach(models,id:\.self){Text($0).tag($0)}}}};Section("验证"){Button("保存并测试连接"){Task{await saveAndTest()}}.fontWeight(.semibold);if let message{Text(message).foregroundStyle(profile.testState == .ok ? .green:.secondary)}};if profile.isConfigured{Section{Button("删除当前渠道",role:.destructive){profile.clearChannel();baseURL="";model="";key="";models=[]}}}}.navigationTitle("模型与渠道").navigationBarTitleDisplayMode(.inline).onAppear{baseURL=profile.baseURL;model=profile.modelName}}
    private func persist(){profile.baseURL=baseURL.trimmingCharacters(in:.whitespacesAndNewlines);profile.modelName=model.trimmingCharacters(in:.whitespacesAndNewlines);if !key.trimmingCharacters(in:.whitespacesAndNewlines).isEmpty{profile.saveAPIKey(key);key=""}}
    private func loadModels()async{persist();loading=true;defer{loading=false};let result=await profile.fetchModelIDs();models=result.0;message=result.1 ?? (models.isEmpty ? "服务未返回模型，可手动填写":"已读取 \(models.count) 个模型");if model.isEmpty,let first=models.first{model=first;profile.modelName=first}}
    private func saveAndTest()async{persist();guard !profile.normalizedBaseURL.isEmpty else{message="请填写服务地址";return};guard profile.hasAPIKey else{message="请填写 API Key";return};guard !profile.modelName.isEmpty else{message="请填写或选择模型";return};await profile.testConnection();switch profile.testState{case .ok:message="连接成功";case .failed(let reason):message=reason;default:break}}
}
